alter table private.review_case_features add column if not exists public_summary text check(public_summary is null or length(public_summary)<=220);
alter table public.reviews disable trigger refresh_contact_rating;
create temp table p4_review_texts(idx int primary key,body text) on commit drop;insert into p4_review_texts values (1,'Перед знакомством выслушали наш запрос и объяснили порядок встречи.'),(2,'Мы принесли короткий список вопросов и успели обсудить главное.'),(3,'Ребёнку дали время осмотреться, не торопили с ответами.'),(4,'Обсудили, как ребёнок общается дома и что важно для семьи.'),(5,'Уточнили, можно ли родителю присутствовать и когда делать перерывы.'),(6,'В начале встречи спокойно познакомились и согласовали формат.'),(7,'Мне было важно получить объяснение простыми словами.'),(8,'После встречи записали договорённости, чтобы ничего не забыть.'),(9,'Условия отмены и стоимость были известны заранее.'),(10,'На вопрос о следующем шаге получили понятный ответ.'),(11,'Понравилось, что сначала спросили о привычках ребёнка.'),(12,'Удобно, что вопросы можно подготовить до визита в приложении.'),(13,'Заранее обсудили чувствительность к шуму и новым людям.'),(14,'На первой встрече больше слушали семью, чем давали общие советы.'),(15,'Объяснили, какие наблюдения стоит обсудить на следующем занятии.'),(16,'Нам помогло заранее увидеть длительность и формат встречи.'),(17,'Когда ребёнок устал, удалось обсудить паузу.'),(18,'Запрос семьи учли при выборе темы первой беседы.'),(19,'Спокойно отнеслись к тому, что ребёнок отвечал не сразу.'),(20,'Родителю объяснили, как задавать дополнительные вопросы после встречи.'),(21,'Обсудили, что уже удобно ребёнку в повседневном общении.'),(22,'Встретились вовремя и уточнили, сколько продлится знакомство.'),(23,'На организационные вопросы ответили до записи.'),(24,'Мы смогли рассказать о трудных ситуациях без сравнения с другими.'),(25,'Уточнили, какие материалы специалисту полезно прочитать заранее.'),(26,'Порядок встречи оказался понятным даже при первом обращении.'),(27,'Семью попросили выбрать один основной вопрос для обсуждения.'),(28,'Обратную связь сформулировали без сложных терминов.'),(29,'Согласовали, как удобнее обмениваться наблюдениями между визитами.'),(30,'Понравилось, что уточнили ожидания родителей от знакомства.'),(31,'Мы обсудили, какие задания уже есть у других участников команды.'),(32,'Во время разговора было достаточно пространства для вопросов.'),(33,'Заранее договорились о сопровождении и привычных способах общения.'),(34,'Мне было удобно видеть запись и договорённости в одном месте.'),(35,'Специалист уточнил, что особенно беспокоит семью сейчас.'),(36,'Обсудили подходящий темп и возможность коротких перерывов.'),(37,'В конце встречи подвели итог и повторили договорённости.'),(38,'Удалось спокойно обсудить вопросы, которые откладывали раньше.');
create temp table p4_review_endings(idx int primary key,body text) on commit drop;insert into p4_review_endings values (1,'Следующую встречу согласовали отдельно.'),(2,'Вопросы по домашним наблюдениям оставили в дневнике.'),(3,'Понравился уважительный тон общения.'),(4,'При необходимости можно уточнить детали в переписке.'),(5,'План дальнейшего общения обсудили с родителем.'),(6,'Осталось понятное представление о следующем шаге.');
