do $$declare j int;aid uuid;rid uuid;begin for j in 1..20 loop aid:=md5('bb-p4-visit-'||'0fd1ef98-0732-d912-be71-a07fdf257fad'||'-'||j)::uuid;rid:=md5('bb-p4-review-'||'0fd1ef98-0732-d912-be71-a07fdf257fad'||'-'||j)::uuid;insert into public.appointments(id,parent_id,child_id,specialist_id,starts_at,ends_at,status,service,reason,contact,visit_verified,is_demo,visited_at) values(aid,md5('bb-prepared-family-'||(j+1))::uuid,md5('bb-prepared-child-'||(j+1))::uuid,'0fd1ef98-0732-d912-be71-a07fdf257fad',now()-make_interval(days=>j+5),now()-make_interval(days=>j+5)+interval '45 minutes','completed','Знакомство и консультация','Обсудить запрос семьи','Переписка в приложении',true,true,now()-make_interval(days=>j+5)) on conflict(id) do nothing;insert into private.visit_confirmations(appointment_id,parent_id,specialist_id,confirmed_at,method) select id,parent_id,specialist_id,visited_at,'demo_fixture' from appointments where id=aid on conflict do nothing;insert into public.reviews(id,parent_id,specialist_id,appointment_id,body,contact,status,evidence,is_demo,visit_verified) select rid,parent_id,specialist_id,id,'Обсудили вопросы семьи и организацию первой встречи.',4,'verified','prompt4-fixture-v20261115',true,true from appointments where id=aid on conflict(id) do nothing;end loop;end$$;
