insert into public.specialists(id,owner_id,name,specialty,city,district,address,price,experience,online,concerns,ages,description,color,published,is_demo,verification_status,profile) values('3251c608-a272-76c1-434f-fbe2a78c556c','d38694c3-2c58-422e-da90-3ba3f0122761','Жанель М.','Помощник семьи','Алматы','Бостандыкский','Алматы, Бостандыкский район · адрес согласуется при записи',6000,6,false,array['speech','communication','other'],array['2–3','4–5','6–8','9–12'],'Помощь с сопровождением, подготовкой к встречам и организацией бытовых дел. Объём помощи и присутствие родителя согласуются заранее. Не оказывает медицинские услуги.','peach',true,true,'approved','{"education":"Подготовка и опыт сопровождения семьи","languages":["Русский","Қазақша"],"cancellation":"Перенос и отмена по договорённости","self_strengths":[]}'::jsonb) on conflict(id) do nothing;
