insert into public.schedule_slots(id,specialist_id,starts_at,ends_at,service,price,available) select md5('bb-p4-slot-'||'3251c608-a272-76c1-434f-fbe2a78c556c'||'-'||(current_date+d)||'-'||h)::uuid,'3251c608-a272-76c1-434f-fbe2a78c556c',((current_date+d)+make_interval(hours=>h)) at time zone 'Asia/Almaty',((current_date+d)+make_interval(hours=>h,mins=>45)) at time zone 'Asia/Almaty','Знакомство и сопровождение',6000,true from generate_series(1,7)d cross join unnest(array[9,11,14,16])h on conflict(id) do nothing;
do $$declare j int;aid uuid;rid uuid;begin for j in 1..20 loop aid:=md5('bb-p4-visit-'||'3251c608-a272-76c1-434f-fbe2a78c556c'||'-'||j)::uuid;rid:=md5('bb-p4-review-'||'3251c608-a272-76c1-434f-fbe2a78c556c'||'-'||j)::uuid;insert into public.appointments(id,parent_id,child_id,specialist_id,starts_at,ends_at,status,service,reason,contact,visit_verified,is_demo,visited_at) values(aid,md5('bb-prepared-family-'||(j+1))::uuid,md5('bb-prepared-child-'||(j+1))::uuid,'3251c608-a272-76c1-434f-fbe2a78c556c',now()-make_interval(days=>j+5),now()-make_interval(days=>j+5)+interval '45 minutes','completed','Знакомство и консультация','Обсудить запрос семьи','Переписка в приложении',true,true,now()-make_interval(days=>j+5)) on conflict(id) do nothing;insert into private.visit_confirmations(appointment_id,parent_id,specialist_id,confirmed_at,method) select id,parent_id,specialist_id,visited_at,'demo_fixture' from appointments where id=aid on conflict do nothing;insert into public.reviews(id,parent_id,specialist_id,appointment_id,body,contact,status,evidence,is_demo,visit_verified) select rid,parent_id,specialist_id,id,'Обсудили вопросы семьи и организацию первой встречи.',4,'verified','prompt4-fixture-v20261115',true,true from appointments where id=aid on conflict(id) do nothing;end loop;end$$;
