do $$declare r record;i int:=0;score int;grp text;age_value numeric;summary text;begin for r in select id,parent_id from public.reviews where specialist_id='493dfc3c-cf9b-4ee9-c177-7d0c3e1047fa' and is_demo and evidence in('demo-fixture-v20261114','contest-fixture-v20261114','prompt4-fixture-v20261115') order by id loop
 i:=i+1;
 if false then score:=case when i<=30 then 5 when i<=32 then 2 else 3 end;grp:=case when i<=30 then 'speech' else 'learning' end;
 elsif false then score:=5;grp:=case when i%3=0 then 'learning' else 'speech' end;
 elsif 0=0 then score:=case when i%4=0 then 5 else 4 end;grp:=case when i%3=0 then 'learning' else 'speech' end;
 elsif 0=1 then score:=case when i%3=0 then 4 else 5 end;grp:=case when i%4=0 then 'learning' else 'speech' end;
 elsif 0=2 then grp:=case when i%4=0 then 'speech' else 'learning' end;score:=case when grp='speech' then 3 else 5 end;
 elsif 0=3 then score:=case when i%5=0 then 3 else 4 end;grp:=case when i%3=0 then 'learning' else 'speech' end;
 elsif 0=4 then score:=case when i%5=0 then 4 else 5 end;grp:=case when i%3=0 then 'learning' else 'speech' end;
 else score:=case when i%2=0 then 5 else 4 end;grp:=case when i%3=0 then 'learning' else 'speech' end;end if;
 age_value:=case when grp='speech' then 3 else 7 end;
 summary:=case when i%3=0 then 'Девочка' else 'Мальчик' end||', '||age_value::int||case when age_value=3 then ' года · речь: пока не использует слова · очно' else ' лет · обучение: трудно выполнять задания · очно' end;
 update public.reviews set contact=score,body=(case when score<=3 then 'Хотелось бы подробнее обсудить следующие шаги. ' else '' end)||(select body from pg_temp.p4_review_texts where idx=1+(i-1)%38)||' '||(select body from pg_temp.p4_review_endings where idx=1+(0+i)%6)||' Специалист: '||'Камила Н.'||'.',created_at=date_trunc('day',now())-make_interval(days=>15+i%7) where id=r.id;
 insert into private.review_case_features(review_id,age,case_group,visit_format,consented_at,public_summary) values(r.id,age_value,grp,'offline',now(),summary) on conflict(review_id) do update set age=excluded.age,case_group=excluded.case_group,visit_format=excluded.visit_format,public_summary=excluded.public_summary;
 end loop;end$$;
