with families as(select id,dense_rank()over(partition by specialist_id order by parent_id) rank from reviews where is_demo and evidence in('demo-fixture-v20261114','contest-fixture-v20261114','prompt4-fixture-v20261115')) update public.reviews r set strengths=array_remove(array[case when f.rank<=12 then 'Понятные объяснения родителям' end,case when f.rank between 6 and 13 then 'Хорошая обратная связь' end,case when f.rank between 12 and 16 then 'Терпеливое отношение' end],null) from families f where r.id=f.id;
alter table public.reviews enable trigger refresh_contact_rating;
update public.specialists s set verified_count=v.review_count,contact_rating=v.overall from private.rating_values(null,null,'any')v where s.id=v.specialist_id;
update public.clinics set district=case when address like '%Култегин%' then 'Нура' when address like '%Туран%' then 'Есильский' when address like '%Валиханова%' then 'Байконурский' when address like '%Ладыгина%' then 'Ауэзовский' else district end where is_demo;
update public.clinic_branches b set district=case when address like '%Култегин%' then 'Нура' when address like '%Туран%' or address like '%Достык%' then 'Есильский' when address like '%Валиханова%' then 'Байконурский' when address like '%Кенесары%' then 'Наурызбайский' when address like '%Ладыгина%' or address like '%5-й микрорайон%' then 'Ауэзовский' else district end where exists(select 1 from clinics c where c.id=b.clinic_id and c.is_demo);
update public.specialists s set district=case when address like '%Култегин%' then 'Нура' when address like '%Туран%' or address like '%Достык%' then 'Есильский' when address like '%Валиханова%' then 'Байконурский' when address like '%Кенесары%' then 'Наурызбайский' when address like '%Ладыгина%' or address like '%5-й микрорайон%' then 'Ауэзовский' else district end where is_demo;
do $$declare a record;begin for a in select * from appointments where parent_id='20000000-0000-4000-8000-000000000001' and is_demo and reason~*'^(п+|а+)$' and not visit_verified and not exists(select 1 from private.booking_payments p where p.appointment_id=appointments.id and p.state in('payment_reported','confirmed')) and not exists(select 1 from reviews r where r.appointment_id=appointments.id) loop delete from appointments where id=a.id;update schedule_slots s set available=true where s.id=a.slot_id and s.starts_at>now() and not exists(select 1 from appointments b where b.slot_id=s.id and b.status in('pending','confirmed','rescheduled','attended'));end loop;end$$;
